tests/container/check.content:
#!/usr/bin/env bash
# Commands in this file execute only inside the isolated tool containers.
set -euo pipefail
shell_checks() {
  shellcheck -x -P SCRIPTDIR tests/*.sh tests/agents/*.sh tests/e2e/*.sh tests/go/*.sh \
    tests/container/run tests/container/check agent/hooks/wrap.sh
}
case "${1:?check category required}" in
  lint)
    [ "$(node --version)" = "$(cat .nvmrc)" ] || { echo 'tests: Node version does not match .nvmrc' >&2; exit 1; }
    golangci-lint config verify
    golangci-lint run --concurrency=4
    formatted=$(golangci-lint fmt --diff)
    [ -z "$formatted" ] || { printf '%s\n' "$formatted"; exit 1; }
    shell_checks
    markdownlint-cli2
    # Configuration validation needs Git metadata, not host release history.
    git init --quiet
    git add -- .
    git -c user.name=Fixture -c user.email=fixture@example.invalid commit --quiet -m 'Validate release configuration'
    git tag v0.0.0
    git remote add origin https://github.com/fixture/project.git
    goreleaser check
    ;;
  shellcheck) shell_checks;;
  test-go)
    if [ ! -w /sys/fs/cgroup/faramir-test/cgroup.procs ] || ! grep -q faramir-test /proc/self/cgroup; then
      echo 'tests: cgroup delegation failed; executor coverage would be skipped' >&2; exit 1
    fi
    [ "$(node --version)" = "$(cat .nvmrc)" ] || { echo 'tests: Node version does not match .nvmrc' >&2; exit 1; }
    go mod verify
    go mod tidy -diff
    go build ./...
    go test -v -race -count=1 -p=1 -parallel=4 -coverprofile=/out/coverage.txt -covermode=atomic ./...
    ;;
  command)
    [ -n "${COMMAND:-}" ] || { echo 'tests: COMMAND is required' >&2; exit 2; }
    exec bash -ec "$COMMAND"
    ;;
  release) goreleaser release --clean --parallelism 4;;
  release-check) goreleaser release --snapshot --clean --skip=publish --parallelism 4;;
  *) echo 'tests: unknown container check' >&2; exit 2;;
esac
if [ "$1" = release ] || [ "$1" = release-check ]; then
  cp -R dist /out/dist
fi

tests/source.sh.content:
#!/usr/bin/env bash
# Archive tracked source with stable metadata, excluding local credentials.
set -euo pipefail
root=$(cd "$(dirname "$0")/.." && pwd -P)

excluded() {
  case "${1,,}" in
    /*|..|../*|*/../*|*/..|.git|.git/*|*/.git|*/.git/*) return 0;;
    agents.md|*/agents.md|claude.md|*/claude.md|gemini.md|*/gemini.md) return 0;;
    .env*|*/.env*|*.env|.dev.vars*|*/.dev.vars*) return 0;;
    .npmrc|*/.npmrc|.netrc|*/.netrc|.pypirc|*/.pypirc|.git-credentials|*/.git-credentials) return 0;;
    .ssh/*|*/.ssh/*|.private/*|*/.private/*|.aws/*|*/.aws/*) return 0;;
    credentials|credentials.*|*/credentials|*/credentials.*|*.pem|*.key|*.crt|*.cer|*.p12|*.pfx|*.age|*.gpg|*.sops.*) return 0;;
  esac
  return 1
}

files() {
  local path parent relative
  while IFS= read -r -d '' path; do
    excluded "$path" && continue
    parent=$(realpath -e -- "$root/$(dirname -- "$path")")
    case "$parent" in
      "$root") relative=$(basename -- "$path");;
      "$root"/*) relative=${parent#"$root/"}/$(basename -- "$path");;
      *) printf 'source: path escapes checkout: %s\n' "$path" >&2; return 1;;
    esac
    if excluded "$relative"; then
      printf 'source: path resolves to an excluded location: %s\n' "$path" >&2
      return 1
    fi
    if [ ! -f "$root/$path" ] && [ ! -L "$root/$path" ]; then
      printf 'source: not a regular file or symlink: %s\n' "$path" >&2
      return 1
    fi
    printf '%s\0' "$path"
  done
}

case "${1:-}" in
  --list) git -C "$root" ls-files -z --cached -- . | files;;
  '')
    git -C "$root" ls-files -z --cached -- . | files |
      tar -C "$root" --no-recursion --null --verbatim-files-from --files-from=- \
        --format=gnu --mtime=@0 --owner=0 --group=0 --numeric-owner \
        --mode='u+rwX,go+rX,go-w' -cf -
    ;;
  *) echo 'source: unknown archive option' >&2; exit 2;;
esac

tests/go/cache.sh.content:
# shellcheck shell=bash
# Docker-owned caches hold dependencies and compiler outputs, never test state.
# Go keys compiler entries by toolchain, inputs and build flags.
go_node_version() {
  local root=$1 version
  [ -f "$root/.nvmrc" ] && [ ! -L "$root/.nvmrc" ] || {
    echo 'tests: Node version input must be a regular file' >&2; return 1
  }
  version=$(cat "$root/.nvmrc")
  [[ "$version" =~ ^v?[0-9]+\.[0-9]+\.[0-9]+$ ]] || {
    echo 'tests: Node version must be pinned to a numeric release' >&2; return 1
  }
  printf '%s\n' "${version#v}"
}
cache_volume() {
  local kind=$1 name=$2 expected
  expected="io.faramir.cache=$kind-v1"
  if [ -z "$(docker volume ls --filter "name=^$name$" --format '{{.Name}}')" ]; then
    docker volume create --label "$expected" "$name" >/dev/null
  fi
  [ "$(docker volume ls --filter "name=^$name$" --filter "label=$expected" --format '{{.Name}}')" = "$name" ] || {
    echo 'tests: cache volume exists without the expected ownership label; refusing to adopt it' >&2
    return 1
  }
}
go_cache_mounts() {
  local name
  for name in "${FARAMIR_GO_MODULE_CACHE:-faramir-go-modules}" "${FARAMIR_GO_BUILD_CACHE:-faramir-go-build}"; do
    [[ "$name" =~ ^[a-zA-Z0-9][a-zA-Z0-9_.-]*$ ]] || {
      printf 'tests: invalid Docker cache volume name: %s\n' "$name" >&2
      return 1
    }
  done
  cache_volume modules "${FARAMIR_GO_MODULE_CACHE:-faramir-go-modules}"
  cache_volume build "${FARAMIR_GO_BUILD_CACHE:-faramir-go-build}"
  # shellcheck disable=SC2034 # The host runners consume this shared argument array.
  GO_CACHE_MOUNTS=(
    --mount "type=volume,source=${FARAMIR_GO_MODULE_CACHE:-faramir-go-modules},target=/go/pkg/mod"
    --mount "type=volume,source=${FARAMIR_GO_BUILD_CACHE:-faramir-go-build},target=/cache"
  )
}
